import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"周易尚氏学 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"周易尚氏学 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"zh/classics/shangshi/049.md","filePath":"zh/classics/shangshi/049.md"}'),h={name:"zh/classics/shangshi/049.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><p>归藏曰夜。古娶必以夜。故曰昏。后阴遇阳。即女遇男。亦婚姤也。是夜与姤义同也。女谓阴。虞翻云。壮伤也。阴伤阳。柔消刚。故曰女壮。勿用取女。戒词也。</p><p>彖。姤。遇也。柔遇刚也。勿用取女。不可与长也。天地相遇。品物咸章也。刚遇中正。天下大行也。姤之时义大矣哉。</p><p>消息卦乾盈于巳。盈则必亏。故至午而一阴生于下。阴遇阳。故曰天地相遇。时当五月。万物洁齐。而巽为草木。为高。为长。故曰品物咸章。荀爽以南方夏位说品物咸章。于象亦切也。五刚既中且正。教化天下。命令大行。如风之博遍。姤五月卦。故曰时。天地相遇。岁功方成。故曰时义大也。郑玄谓姤一女当五男。非礼之正。故谓之振。女壮以淫。故不可取。而朱子喜用其说。便谓女德不贞。于易理太不类也。</p><p>象曰。天下有风。姤。后以施树四方。</p><p>复冬至。姤夏至。易林复之履云。先王日至。不利出城。又晋之解云。二至之戒。家无凶祸。故复象云。先王以至日闭关。商旅不行。后不省方。至日。王弼孔颖达皆谓二至。又汉书薛宣传。至日休吏。由来已久。注。至日夏至冬至也。盖古时视二至最重。自周讫南宋。可考见者。至日皆停止工作。乾为后。巽为命。伏坤为四方。后以施命浩四方者。言君以夏至之日。施命令止四方行旅也。后汉鲁恭传。说此。最合古义。详焦氏易诂中。</p><p>初六。系于金柅。贞吉。有攸往。见凶。赢豕孚蹢躅。</p><p>巽为绳。故曰系。巽木乾金。故曰金柅。马融云。柅在车下。所以止轮。释文广雅云。止也。说文作称（左木）。云络丝趺。按今本说文。跌讹为称（左木）。云人木称（左木）声。读若柅。陶庐云。古从尔从柅之字。同音通用。毛诗饮饯于尔（左 ）。韩诗作坭。书典祀勿。丰于呢。释文引马云考也。谓称庙也。然则柅称（左木）古通用。后儒必谓尔（左木）是者非也。况马君训作止车木。可证古文原作柅。若为尔（左木）。马君能有异说哉。按络丝者。络丝之器。王肃所谓柅织绩之器。妇人用者是也。趺者横木。安络器下。以防欹侧。在下似足。故谓之跌。唐阴宏道云。络器。关西谓之络垛。梁益谓之丝登。其下附（左木）即柅也。按阴氏所谓附（左木）。即说文之趺。故玉篇即作络丝附（左木）。陈寿棋云。附（左木）趺同字。络缚也。与系同义。系于金尼者。言以丝缚于金柅之上。止而勿动。以喻阴不宜动而消阳。故下云往见凶。是其义也。贞吉者。卜问吉。往见凶者。进则凶也。巽为赢（下中羊）为豕。巽进退。故蹢躅。羸释文陆读为累。郑力追反。是仍读为累。与大壮同。累缠绕也。羸累累音同通用。巽为绳故为赢。巽伏故亦为豕。蹢躅动也。羸豕孚蹢躅者。言豕虽拘赢。然蹢躅前进。信其必然。不可忽也。喻阴虽微。后必长也。巽豕象失传。详焦氏易诂易象补遗。</p><h3 id="象曰。系于金柅。柔道牵也。" tabindex="-1">象曰。系于金柅。柔道牵也。 <a class="header-anchor" href="#象曰。系于金柅。柔道牵也。" aria-label="Permalink to “象曰。系于金柅。柔道牵也。”">​</a></h3><p>玉篇。牵速也。下九三。象释其行次且。曰行未牵也。是象传亦训牵为速。柔道牵者。言柔之为道。消阳甚速。故以金柅止之。诸家皆谓柔牵于二。失经旨。经旨恐阴进危阳。故止其动。象释为柔道牵。申系于金柅之故也。牵速之象取风疾。兼取巽绳。</p><p>九二。苞有鱼。无咎。不利实。</p><p>苞今本作包。书禹贡草木渐包。释文或作苞。是包苞古通。故虞氏作苞。见释文。虞云巽为白茅。诗白茅苞之。巽为鱼。二据阴居中。故曰苞有鱼。巽为宾客。不利宾者。宾指上四阳。言初为二所据。四阳不能及初也。子夏传作庖。而荀爽则作胞。胞 通。是皆以庖厨为义。然卦元是象。故虞氏合也。</p><h3 id="象曰。苞有鱼。义不及宾也。" tabindex="-1">象曰。苞有鱼。义不及宾也。 <a class="header-anchor" href="#象曰。苞有鱼。义不及宾也。" aria-label="Permalink to “象曰。苞有鱼。义不及宾也。”">​</a></h3><p>二近。宾远。故义不及。</p><p>九三。臀无肤。其行次且。厉。无大咎。</p><p>三居下卦之末。故亦曰臀。初阴爻。下烂。故曰无肤。乾为行。三得敌。故次且不前。然三当位。故虽危厉而无大咎也。旧解皆不知次且之故何在。而以复震为行为说。失之远矣。</p><h3 id="象曰。其行次且。行未牵也。" tabindex="-1">象曰。其行次且。行未牵也。 <a class="header-anchor" href="#象曰。其行次且。行未牵也。" aria-label="Permalink to “象曰。其行次且。行未牵也。”">​</a></h3><p>行未牵。即行未速。次且者却行未前。故日未速。</p><p>九四。 苞无鱼。起凶。</p><p>四应初。疑于有鱼。岂知初已为二所据。实无鱼也。无鱼则勿动。动应初则为二三所害。故凶。起作也。</p><h3 id="象曰。无鱼之凶。远民也。阴为民。言四距初远。故无鱼也。" tabindex="-1">象曰。无鱼之凶。远民也。阴为民。言四距初远。故无鱼也。 <a class="header-anchor" href="#象曰。无鱼之凶。远民也。阴为民。言四距初远。故无鱼也。" aria-label="Permalink to “象曰。无鱼之凶。远民也。阴为民。言四距初远。故无鱼也。”">​</a></h3><p>九五。以把苞瓜。含章。有陨自天。</p><p>下巽为杞。上乾为圜。为瓜。孟子告于曰。以人性为仁义。犹以杞柳为否（左木）卷（左木）。说文否（左木）？也。卷（左木）屈木盂也。以杞苞瓜者。言以杞柳之器盛瓜也。乾为大明。故曰章。瓜为所苞。故曰含章。五承乘皆阳。行窒。故含章自守。五天位。巽为陨。有陨自天者。言不久明消至二。五与为应。有陨落之险也。知其险而预为之备。则得矣。此圣人防微虑远之意也。自荀虞以来。皆不知左传有风陨象。因之清儒亦皆不知。于是虞氏令四陨初之说。沿袭至今。而经义全晦。复六五曰敦复无侮。待阳息至二。五有应而古。此则庐阳消至二。五应之而凶。</p><h3 id="象曰。九五含章。中正也。有陨自天。志不舍命也。" tabindex="-1">象曰。九五含章。中正也。有陨自天。志不舍命也。 <a class="header-anchor" href="#象曰。九五含章。中正也。有陨自天。志不舍命也。" aria-label="Permalink to “象曰。九五含章。中正也。有陨自天。志不舍命也。”">​</a></h3><p>巽为命。舍命谓任命也。志不舍命者。言知其后有陨落之险。不任命而预防之也。</p><p>上九。柅其角。吝。无咎。</p><p>乾为首。上九居乾之上。角之象也。故曰姤其角。然亦无大咎也。</p><h3 id="象曰。柅其角。上穷吝也。" tabindex="-1">象曰。柅其角。上穷吝也。 <a class="header-anchor" href="#象曰。柅其角。上穷吝也。" aria-label="Permalink to “象曰。柅其角。上穷吝也。”">​</a></h3><p>处亢龙之位。故穷吝。</p>',29)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
